<script setup lang="ts">
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { chooseUpload, getToken, previewFile, request } from '../../api'
import { money, orderTime, orderStatus, type Order, type OrderPage } from '../../../../shared/orders'
const orders=ref<Order[]>([]), selected=ref<Order|null>(null), busy=ref(false), error=ref(''), reason=ref('')
const page=ref(0), total=ref(0), shipment=ref({carrier:'',tracking_no:'',proof_file_id:0})
async function run(action:()=>Promise<void>) { if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false} }
async function load(reset=true) { const next=reset?1:page.value+1;const data=await request<OrderPage>('/merchant/orders?page='+next);orders.value=reset?data.items:[...orders.value,...data.items];page.value=next;total.value=data.total; if(selected.value) selected.value=await request<Order>('/orders/'+selected.value.id) }
onShow(()=>{if(!getToken()){uni.reLaunch({url:'/pages/login/index'});return};run(()=>load())})
function detail(o:Order) { return run(async()=>{selected.value=await request<Order>('/orders/'+o.id);reason.value='';shipment.value={carrier:'',tracking_no:'',proof_file_id:0}}) }
function upload() { return run(async()=>{shipment.value.proof_file_id=(await chooseUpload('SHIPMENT')).id}) }
function action(name:string) { const o=selected.value;if(!o)return;uni.showModal({title:({CONFIRM:'确认接单',REJECT:'拒绝订单',SHIP:'确认发货'} as Record<string,string>)[name],content:name==='REJECT'?'拒绝后订单取消并释放库存。':'请核对订单和操作信息。',success:r=>{if(r.confirm)run(async()=>{selected.value=await request<Order>('/orders/'+o.id+'/actions','POST',{version:o.version,action:name,reason:reason.value,...(name==='SHIP'?shipment.value:{})});await load()})}}) }
function preview(id:number) { return run(()=>previewFile(id)) }
</script>
<template><view class="screen"><view class="top"><text class="title">商家订单</text><button size="mini" :disabled="busy" @click="run(()=>load())">刷新</button></view><text class="notice">模拟履约 · 请使用测试运单与凭证</text><view v-if="error" class="error">{{ error }}</view>
<view v-if="selected" class="card"><button class="secondary" @click="selected=null">返回订单列表</button><text class="heading">{{ orderStatus(selected.status) }} · ¥ {{ money(selected.total_amount) }}</text><text>{{ selected.order_no }}</text><text>{{ selected.address_snapshot.recipient }} · {{ selected.address_snapshot.phone }}<br/>{{ selected.address_snapshot.address }}</text><view v-for="i in selected.items" :key="i.id" class="line"><text class="heading">{{ i.product_name }}</text><text>{{ i.sku_code }} · ¥ {{ money(i.unit_price) }} × {{ i.quantity }} {{ i.unit }}</text><text>{{ Object.values(i.specification).filter(Boolean).join(' · ') }}</text><button v-if="i.cover_file_id" class="secondary" size="mini" @click="preview(i.cover_file_id)">查看商品快照图片</button><text v-if="i.review">评价 {{ i.review.rating }} 星 · {{ i.review.content }}</text></view>
<view v-if="selected.status==='PENDING_CONFIRM'"><input v-model="reason" placeholder="拒绝原因（拒绝时必填）" maxlength="500"/><button :disabled="busy" @click="action('CONFIRM')">确认接单</button><button class="secondary" :disabled="busy" @click="action('REJECT')">拒绝订单</button></view>
<view v-if="selected.status==='TO_SHIP'"><text class="heading">录入模拟发货信息</text><input v-model="shipment.carrier" placeholder="承运方" maxlength="80"/><input v-model="shipment.tracking_no" placeholder="模拟运单号" maxlength="100"/><button class="secondary" :disabled="busy" @click="upload">{{ shipment.proof_file_id?'重新上传发货凭证':'上传发货凭证' }}</button><button v-if="shipment.proof_file_id" class="secondary" @click="preview(shipment.proof_file_id)">预览凭证</button><button :disabled="busy" @click="action('SHIP')">确认发货</button></view>
<view v-if="selected.shipment"><text>承运方：{{ selected.shipment.carrier }}<br/>运单号：{{ selected.shipment.tracking_no }}</text><button class="secondary" @click="preview(selected.shipment.proof_file_id)">查看发货凭证</button></view><text v-if="selected.cancellation_reason">取消原因：{{ selected.cancellation_reason }}</text><text class="heading">订单轨迹</text><text v-for="(e,index) in selected.events" :key="index" class="notice">{{ orderTime(e.created_at) }} · {{ orderStatus(e.to_status) }} {{ e.reason }}</text></view>
<view v-else><text v-if="!busy&&!orders.length" class="notice">暂无订单，顾客提交模拟订单后会显示在这里。</text><view v-for="o in orders" :key="o.id" class="card" @click="detail(o)"><text class="heading">{{ orderStatus(o.status) }} · ¥ {{ money(o.total_amount) }}</text><text>{{ o.items.map(i=>i.product_name).join('、') }}</text><text>{{ orderTime(o.created_at) }} · 查看详情 →</text></view><button v-if="orders.length<total" :disabled="busy" @click="run(()=>load(false))">加载更多</button></view>
</view></template>
<style scoped>
.screen{max-width:760px;margin:auto;min-height:100vh;padding:32rpx;background:#f5f6ef;color:#2c4238}.top{display:flex;justify-content:space-between;align-items:center}.title{font-size:40rpx;font-weight:700}.notice{display:block;color:#7c8873;font-size:24rpx;line-height:1.8}.card{background:white;padding:30rpx;margin:24rpx 0;border-radius:16rpx;font-size:26rpx;line-height:1.8;display:flex;flex-direction:column;gap:18rpx;word-break:break-all}.heading{font-size:30rpx;font-weight:600}.line{padding:20rpx 0;border-bottom:1px solid #eee;display:flex;flex-direction:column;gap:14rpx}.error{background:#fcece6;color:#a04436;padding:22rpx}button{background:#315745;color:white;font-size:26rpx;margin:18rpx 0;border-radius:10rpx}button::after{border:0}button.secondary{background:#e8eddf;color:#315745}input{box-sizing:border-box;width:100%;height:80rpx;padding:18rpx;background:#f4f5ed;font-size:26rpx;margin:18rpx 0}
</style>
